// SSD Performance Metrics (Conceptual)
struct SSD_Metrics {
    // Sequential Performance (Large transfers)
    long SeqRead_MBps;
    long SeqWrite_MBps;

    // Random Performance (Small 4KB I/O)
    long RandRead_IOPS;
    long RandWrite_IOPS;

    // Latency
    int ReadLatency_us;      // Microseconds
    int WriteLatency_us;
};

// Endurance and Write Amplification Factor (WAF)
typedef long long TBW_Value; // Total Bytes Written capacity

// Data written by host vs actual data written to flash
float HOST_WRITES = 100.0e9;
float FLASH_WRITES = 150.0e9;

// WAF = Actual Writes / Host Writes (WAF >= 1.0)
const float WAF = FLASH_WRITES / HOST_WRITES;

const float DWPD_RATING = 1.0; // Drive Writes Per Day

// Wear Leveling Data Structure (Flash Block Tracking)
#define MAX_P_E_CYCLES 3000 // Program/Erase Cycles (Endurance)

struct FlashBlock {
    int logical_page_map_id;
    int physical_block_id;
    int erase_count;        // Key metric for wear leveling
    bool is_free;
};

// Core wear leveling goal: Select the block with the lowest erase count
FlashBlock* select_write_target(FlashBlock blocks[]) {
    FlashBlock* target = blocks[0];
    for (int i = 1; i < N_BLOCKS; i++) {
        if (blocks[i].erase_count < target->erase_count)
            target = blocks[i];
    }
    return target;
}
